/**
 * Calling this on a conversation with no running turn also returns 204 rather than an error — the user pressing stop races with the turn finishing on its own, and both outcomes are the same. This operation remains available while the project is suspended or being cleaned up.
 * @summary Interrupt a running turn
 */
export const interruptThread = async (
  thread: string,
  options?: RequestInit,
  fetchFn?: typeof globalThis.fetch,
): Promise<interruptThreadResponse> => {
  const res = await (fetchFn ?? fetch)(getInterruptThreadUrl(thread), {
    ...options,
    method: "POST",
  });

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: interruptThreadResponse["data"] = body ? JSON.parse(body) : undefined;
  return { data, status: res.status, headers: res.headers } as interruptThreadResponse;
};

export type sendMessageResponse202 = {
  data: TurnIDResponseBody;
  status: 202;
};

export type sendMessageResponseDefault = {
  data: Error;
  status: Exclude<HTTPStatusCodes, 202>;
};

export type sendMessageResponseSuccess = sendMessageResponse202 & {
  headers: Headers;
};
export type sendMessageResponseError = sendMessageResponseDefault & {
  headers: Headers;
};

export type sendMessageResponse = sendMessageResponseSuccess | sendMessageResponseError;

export const getSendMessageUrl = (thread: string) => {
  return `https://assistant.leaflow.cloud/api/v1/threads/${encodeURIComponent(String(thread))}/messages`;
};

/**
 * Returns a turnId immediately without waiting for execution — a turn can run for tens of minutes. Progress arrives on the live stream the conversation document's `stream` points at, not in this response. Sending while the assistant is still working is allowed: the message is put in line and `queued` comes back true, to be read at the next step of the turn already running — so the editor should stay open rather than blocking on a busy conversation.
 * @summary Send a message and start a turn
 */
export const sendMessage = async (
  thread: string,
  sendMessageRequestBody: SendMessageRequestBody,
  options?: RequestInit,
  fetchFn?: typeof globalThis.fetch,
): Promise<sendMessageResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  const res = await (fetchFn ?? fetch)(getSendMessageUrl(thread), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(sendMessageRequestBody),
  });

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: sendMessageResponse["data"] = body ? JSON.parse(body) : {};
  return { data, status: res.status, headers: res.headers } as sendMessageResponse;
};

