/**
 * Reverts the entry at `ordinal` and everything after it. Reverted entries stay in the transcript marked `reverted`, and ordinals are not renumbered. Returns how many were actually reverted.
 * @summary Revert from a given point
 */
export const revertThread = async (
  thread: string,
  revertRequestBody: RevertRequestBody,
  options?: RequestInit,
  fetchFn?: typeof globalThis.fetch,
): Promise<revertThreadResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  const res = await (fetchFn ?? fetch)(getRevertThreadUrl(thread), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(revertRequestBody),
  });

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: revertThreadResponse["data"] = body ? JSON.parse(body) : {};
  return { data, status: res.status, headers: res.headers } as revertThreadResponse;
};
